// ============================================================
// Scaleway Billing Forecast
// ============================================================
// Sums current-month Scaleway consumption, converts EUR → USD
// using today's exchange rate, and projects end-of-month spend.
// Outputs Slack Block Kit blocks array + fallback text.
// ============================================================

const consumption = $('Get Scaleway Consumption').first().json;
const exchangeData = $('Get EUR/USD Rate').first().json;

// --- Sum consumption ------------------------------------------
// Scaleway Money type: { currency_code, units (int64), nanos (int32) }
// Total = units + nanos / 1e9
const items = consumption.consumptions || [];
let totalEur = 0;
for (const item of items) {
  if (item.value) {
    totalEur += Number(item.value.units || 0) + Number(item.value.nanos || 0) / 1e9;
  }
}

// --- EUR → USD conversion ------------------------------------
const eurToUsd = exchangeData.rates?.USD || 1.08;
const totalUsd = totalEur * eurToUsd;

// --- Date math ------------------------------------------------
const now = new Date();
const daysInMonth = new Date(now.getFullYear(), now.getMonth() + 1, 0).getDate();
const dayOfMonth = now.getDate();
const daysRemaining = daysInMonth - dayOfMonth;

// --- Linear projection ----------------------------------------
const dailyRate = dayOfMonth > 0 ? totalUsd / dayOfMonth : 0;
const projectedEom = dailyRate * daysInMonth;

const THRESHOLD_USD = 200;
const overBudget = projectedEom >= THRESHOLD_USD;

// --- Helpers --------------------------------------------------
const fmt = (n) => Number(n).toFixed(2);
const monthName = now.toLocaleString('en-US', { month: 'long' });
const pctDone = Math.round((dayOfMonth / daysInMonth) * 10);
const bar = '\u2588'.repeat(pctDone) + '\u2591'.repeat(10 - pctDone);

// --- Slack Block Kit ------------------------------------------
const emoji = overBudget ? '\ud83d\udea8' : '\u2705';
const statusText = overBudget
  ? `Projected to *exceed* $${THRESHOLD_USD} threshold`
  : `Projected to stay *under* $${THRESHOLD_USD} threshold`;

const blocks = [
  {
    type: 'header',
    text: {
      type: 'plain_text',
      text: `${emoji} Scaleway Billing \u2014 ${monthName} ${now.getFullYear()}`,
      emoji: true
    }
  },
  {
    type: 'section',
    text: { type: 'mrkdwn', text: statusText }
  },
  {
    type: 'section',
    fields: [
      { type: 'mrkdwn', text: `*Spend to date:*\n$${fmt(totalUsd)} (\u20ac${fmt(totalEur)})` },
      { type: 'mrkdwn', text: `*Projected EOM:*\n$${fmt(projectedEom)}` },
      { type: 'mrkdwn', text: `*Daily burn:*\n$${fmt(dailyRate)}/day` },
      { type: 'mrkdwn', text: `*EUR\u2192USD rate:*\n${eurToUsd.toFixed(4)}` }
    ]
  },
  {
    type: 'context',
    elements: [
      {
        type: 'mrkdwn',
        text: `${bar}  Day ${dayOfMonth} of ${daysInMonth} \u00b7 ${daysRemaining} days remaining`
      }
    ]
  }
];

const fallbackText = `${emoji} Scaleway Billing: $${fmt(totalUsd)} spent, $${fmt(projectedEom)} projected EOM`;

return [{ json: { blocks, fallbackText } }];
